_SPECIAL_ALIASES = {'D': (1, 2), 'T': (1, 3)}

_SYMBOL_TO_Z = {}
for (_z, _a), _n in NUCLIDES.items():
    _SYMBOL_TO_Z.setdefault(_n.symbol, _z)


def _int_exact(value, what):
    if isinstance(value, bool) or not isinstance(value, int):
        if isinstance(value, float) and value.is_integer():
            raise KeyError(
                f'{what} must be an integer, got float {value!r}; pass an '
                f'int to avoid silent misidentification')
        raise KeyError(f'{what} must be an integer, got {value!r}')
    return value


def lookup(key) -> Nuclide:
    """Resolve a nuclide: 'C' (natural), '13-C'/'C-13', 'D', or (Z, A).

    Element symbols and (Z, 0) tuples resolve to the natural-element
    entry, whose constants are abundance-averaged; A=0 entries must not
    be used for ENDF ZA identity (use most_abundant_a / an explicit
    isotope). Isotope labels require A >= 1.
    """
    if isinstance(key, tuple):
        if len(key) != 2:
            raise KeyError(f'nuclide tuple must be (Z, A), got {key!r}')
        z = _int_exact(key[0], 'Z')
        a = _int_exact(key[1], 'A')
        if z < 1 or a < 0:
            raise KeyError(f'nuclide (Z={z}, A={a}) out of range')
        try:
            return NUCLIDES[(z, a)]
        except KeyError:
            raise KeyError(
                f'no neutron data for nuclide (Z={z}, A={a}); pass explicit '
                f'constants via the species override instead') from None
    s = str(key).strip()
    if s in _SPECIAL_ALIASES:
        return lookup(_SPECIAL_ALIASES[s])
    if '-' in s:
        left, right = s.split('-', 1)
        if left.isdigit():
            a, sym = int(left), right
        elif right.isdigit():
            sym, a = left, int(right)
        else:
            raise KeyError(f'cannot parse nuclide label {s!r}')
        if a < 1:
            raise KeyError(
                f'isotope label {s!r} needs A >= 1; use the bare element '
                f'symbol for natural-composition constants')
        z = _SYMBOL_TO_Z.get(sym)
        if z is None:
            raise KeyError(f'unknown element symbol {sym!r} in {s!r}')
        return lookup((z, a))
    z = _SYMBOL_TO_Z.get(s)
    if z is None:
        raise KeyError(
            f'unknown element or nuclide {s!r}; pass explicit constants '
            f'via the species override instead')
    return NUCLIDES[(z, 0)]


def most_abundant_a(z: int) -> int:
    """Mass number of the most abundant natural isotope of element Z.

    Raises for fully synthetic elements (no natural composition exists,
    so no default identity can be chosen; pass an explicit isotope).
    """
    z = _int_exact(z, 'Z')
    try:
        return MOST_ABUNDANT_A[z]
    except KeyError:
        raise KeyError(
            f'element Z={z} has no natural isotopic composition; choose '
            f'an explicit isotope for the ZA identity') from None
